    \'html\' => \'<script>$nc(function() {
 let displayAs = $nc(\\\'[name="custom_settings[displayAs]"]\\\'),
     userField = $nc(\\\'[name="custom_settings[userField]"]\\\'),
     textSpace = $nc(\\\'[name="custom_settings[textSpace]"]\\\'),
