   var authVal = displayAuth.val();
   var showIconModes = ["text_icon_left", "text_icon_top", "icon"];
   var showIcon = (showIconModes.indexOf(guestVal) !== -1) || (showIconModes.indexOf(authVal) !== -1);
   
   if(showIcon) { iconFields.closest(".nc-field").show(); } 
   else { iconFields.closest(".nc-field").hide(); }
