$nc(function() {
 var selector = $nc(\\\'[name="custom_settings[fieldWidth]"]\\\'), size = $nc(\\\'[name="custom_settings[fieldWidthSize]"]\\\'), units = $nc(\\\'[name="custom_settings[fieldWidthUnit]"]\\\');
 selector.on("change",function(){
  if($nc(this).val()==\\\'set\\\') {
   size.parent().show();
   units.parent().show();
