  array (
    \'type\' => \'custom\',
    \'subtype\' => NULL,
    \'caption\' => \'js код\',
    \'initial_value\' => \'\',
    \'skip_in_form\' => \'0\',
    \'html\' => \'<script>$nc(function () {
        const displayAs = $nc("[name=\\\'custom_settings[displayAs]\\\']");
        const iconPosition = $nc("[name=\\\'custom_settings[iconPosition]\\\']");
        const iconParams = $nc("[name^=\\\'custom_settings[icon\\\']");
        const linkOn = $nc("[name=\\\'custom_settings[linkOn]\\\']");
        const textSpace = $nc("[name=\\\'custom_settings[textSpace]\\\']");
        const decor = $nc("[name=\\\'custom_settings[iconDecor]\\\']");
        const decorColor = $nc("[name=\\\'custom_settings[iconDecorColor]\\\']");

        displayAs.on("change", function () {
            const val = $nc(this).val();

            if (val === "full") {
                linkOn.parent().show();
                textSpace.parent().show();
            } else {
                linkOn.parent().hide();
                textSpace.parent().hide();
            }

            if (val === "full" || val === "icon") {
                iconParams.parent().show();
                iconPosition.trigger("change");
            } else {
                iconParams.parent().hide();
            }
        }).trigger("change");

        decor.on("change", function () {
            if ($nc(this).val() === "none") {
                decorColor.parent().hide();
            } else {
                decorColor.parent().show();
            }
        }).trigger("change");
    });
</script>\',
  ),
  \'icon_default\' => 
