    \'html\' => \'<script>$nc(function () {
        const decor = $nc("[name=\\\'custom_settings[icon_decor]\\\']");
        const decorColor = $nc("[name=\\\'custom_settings[icon_decor_color]\\\']");
        const iconPosition = $nc("[name=\\\'custom_settings[icon_position]\\\']");
        const iconSettings =  $nc(iconPosition).parents(".nc-field").nextAll(".nc-field");

        iconPosition.on("change", function () {
            if ($nc(this).val() === "icon-none") {
                iconSettings.hide();
            } else {
                iconSettings.show();
            }
        }).trigger("change");

        decor.on("change", function () {
            if ($nc(this).val() === "none") {
