    \'skip_in_form\' => \'0\',
    \'html\' => \'<script>$nc(function () {
        let showAs = $nc("[name=\\\\"custom_settings[show_as]\\\\"]"),
            icon_params = $nc("[name^=\\\\"custom_settings[icon\\\\"]"),
            space_text = $nc("[name=\\\\"custom_settings[text_space]\\\\"]");
        let decor = $nc("[name=\\\\"custom_settings[icon_decor]\\\\"]"),
            decorColor = $nc("[name=\\\\"custom_settings[icon_decor_color]\\\\"]");

        showAs.on("change", function () {
            if ($nc(this).val() === "all" || $nc(this).val() === "icon") {
                icon_params.each(function () { $nc(this).parent().show(); });

                if ($nc(this).val() === "icon") {
                    $nc("[name^=\\\\"custom_settings[icon_position\\\\"]").parent().hide();
                    space_text.parent().hide();
                } else {
                    space_text.parent().show();
                }
            } else {
                icon_params.each(function () { $nc(this).parent().hide(); });
                space_text.parent().hide();
            }
        }).trigger("change");

        decor.on("change", function () {
            if ($nc(this).val() === "none") {
                decorColor.parent().hide();
            } else {
                decorColor.parent().show();
            }
        }).trigger("change");
    });</script>
\',
  ),
);',
