    \'caption\' => \'js код\',
    \'initial_value\' => \'\',
    \'skip_in_form\' => \'0\',
    \'html\' => \'<script>$nc(function() { 
 let showAs = $nc(\\\'[name="custom_settings[showAs]"]\\\');
     icon_params = $nc(\\\'[name^="custom_settings[icon"]\\\'), 
     space_text = $nc(\\\'[name="custom_settings[textSpace]"]\\\'), 
     iconAlign = $nc(\\\'[name="custom_settings[iconAlign]"]\\\');
 let decor = $nc(\\\'[name="custom_settings[iconDecor]"]\\\'), 
     decorColor = $nc(\\\'[name="custom_settings[iconDecorColor]"]\\\');    
 
 showAs.on("change",function(){ 
   if($nc(this).val()===\\\'all\\\' || $nc(this).val()===\\\'icon\\\') { 
     icon_params.each(function(){ $nc(this).parent().show(); }); 
     space_text.parent().show(); 
     iconAlign.parent().show(); 
   } else { 
     icon_params.each(function(){ $nc(this).parent().hide(); });
     space_text.parent().hide();
     iconAlign.parent().hide(); 
   } 
 }).trigger("change");
 decor.on("change",function(){ 
   if($nc(this).val()===\\\'none\\\') { 
     decorColor.parent().hide(); 
   } else { 
     decorColor.parent().show(); 
   } 
 }).trigger("change"); 
});</script>\',
  ),
