  \'js\' => 
  array (
    \'type\' => \'custom\',
    \'subtype\' => NULL,
    \'caption\' => \'Скрипт\',
    \'initial_value\' => \'\',
    \'skip_in_form\' => \'0\',
    \'html\' => \'<script>$nc(function () {
        const fieldName = $nc("[name=\\\'custom_settings[field_name]\\\']");
        const dateTimeFormatSettings = $nc("[name=\\\'custom_settings[datetime_format]\\\']");
        const dateTimeFormatSettingsWrapper = dateTimeFormatSettings.parent();
        const customDateTimeFormat = $nc("[name=\\\'custom_settings[custom_datetime_format]\\\']")
        const customDateTimeFormatWrapper = customDateTimeFormat.parent();
        const imageRatio = $nc("[name=\\\'custom_settings[image_ratio]\\\']");
        const imageRatioWrapper = imageRatio.parent();
        const customImageRatio = $nc("[name=\\\'custom_settings[custom_image_ratio]\\\']");
        const customImageRatioWrapper = customImageRatio.parent();
        const formatHint = $nc(`<ul class="format-hint" style="display: none;">
                                    <li><strong>d</strong>: день месяца (01 до 31)</li>
                                    <li><strong>m</strong>: Месяц (01 до 12)</li>
                                    <li><strong>Y</strong>: Год (4 цифры)</li>
                                    <li><strong>y</strong>: Год (2 цифры)</li>
                                    <li><strong>D</strong>: Сокращенное название дня недели (например, "Пн")</li>
                                    <li><strong>F</strong>: Полное название месяца (например, "Октябрь")</li>
                                    <li><strong>H</strong>: Час в 24-часовом формате (00 до 23)</li>
                                    <li><strong>h</strong>: Час в 12-часовом формате (01 до 12)</li>
                                    <li><strong>i</strong>: Минуты с ведущими нулями (00 до 59)</li>
                                    <li><strong>s</strong>: Секунды с ведущими нулями (00 до 59)</li>
                                </ul>`);
        customDateTimeFormatWrapper.after(formatHint);

        fieldName.on("change", function () {
                const fieldType = $nc(this).find(":selected").data("field-type");
                dateTimeFormatSettingsWrapper.hide();
                imageRatioWrapper.hide();
                customImageRatioWrapper.hide();

                // Дата и время
                if (fieldType == 8) {
                    dateTimeFormatSettingsWrapper.show();
                }
                // Файлы
                else if (fieldType == 6) {
                    imageRatioWrapper.show();
                }
            })
            .trigger("change");

        dateTimeFormatSettings.on("change", function () {
                if ($nc(this).val() === "custom") {
                    customDateTimeFormatWrapper.show();
                    formatHint.show();
                } else {
                    customDateTimeFormatWrapper.hide();
                    customDateTimeFormat.val("");
                    formatHint.hide();
                }
            })
            .trigger("change");

        imageRatio.on("change", function () {
                if ($nc(this).val() === "custom") {
                    customImageRatioWrapper.show()
                } else {
                    customImageRatioWrapper.hide();
                    customImageRatio.val("");
                }
            })
            .trigger("change");
    });
</script>\',
  ),
);',
