    \'type\' => \'string\',
    \'subtype\' => NULL,
    \'caption\' => \'Разделитель между элементами\',
    \'initial_value\' => \'/\',
    \'skip_in_form\' => \'0\',
    \'validate_regexp\' => \'\',
    \'validate_error\' => \'\',
