    \'initial_value\' => \'\',
    \'skip_in_form\' => \'0\',
    \'html\' => \'<script>$nc(function() {
 let showCatalogueLink = $nc(\\\'[name="custom_settings[showCatalogueLink]"]\\\'),
     catalogueLinkAs = $nc(\\\'[name="custom_settings[catalogueLinkAs]"]\\\'),
     iconParts = $nc(\\\'[name^="custom_settings[icon"]\\\').parent(),
     customNameDiv = $nc(\\\'[name="custom_settings[customName]"]\\\').parent();

 showCatalogueLink.on("change", function() {
     customNameDiv.hide();
     iconParts.hide();
     if($nc(this).prop("checked")) {
         catalogueLinkAs.parent().show(); catalogueLinkAs.trigger("change");
     } else {
         catalogueLinkAs.parent().hide();
     }
 }).trigger("change");

 catalogueLinkAs.on("change", function() {
     if($nc(this).val() === "customname") { customNameDiv.show(); } else { customNameDiv.hide(); }
     if($nc(this).val() === "icon") { iconParts.show(); } else { iconParts.hide(); }
 });

});</script>\',
