    'CustomSettingsTemplate' => '$settings_array = array (
  \'display_as\' => 
  array (
    \'type\' => \'select\',
    \'subtype\' => \'static\',
    \'caption\' => \'Выводить элементы как\',
    \'default_value\' => \'a\',
    \'initial_value\' => \'a\',
    \'skip_in_form\' => \'0\',
    \'values\' => 
    array (
      \'li\' => \'Список (li)\',
      \'a\' => \'Ссылка (а)\',
      \'button\' => \'Кнопка (button)\',
    ),
  ),
  \'li_style\' => 
  array (
    \'type\' => \'select\',
    \'subtype\' => \'static\',
    \'caption\' => \'Формат списка\',
    \'default_value\' => \'dots\',
    \'initial_value\' => \'dots\',
    \'skip_in_form\' => \'0\',
    \'values\' => 
    array (
      \'dots\' => \'С буллитами\',
      \'outDots\' => \'Без буллитов\',
    ),
  ),
  \'title_classname\' => 
  array (
    \'type\' => \'select\',
    \'subtype\' => \'static\',
    \'caption\' => \'Шрифт заголовка\',
    \'default_value\' => \'tpl-text-header6\',
    \'initial_value\' => \'tpl-text-header6\',
    \'skip_in_form\' => \'0\',
    \'values\' => 
    array (
      \'tpl-text-default\' => \'Обычный\',
      \'tpl-text-header1\' => \'Заголовок 1\',
      \'tpl-text-header2\' => \'Заголовок 2\',
      \'tpl-text-header3\' => \'Заголовок 3\',
      \'tpl-text-header4\' => \'Заголовок 4\',
      \'tpl-text-header5\' => \'Заголовок 5\',
      \'tpl-text-header6\' => \'Заголовок 6\',
    ),
  ),
  \'html\' => 
  array (
    \'type\' => \'custom\',
    \'subtype\' => NULL,
    \'caption\' => \'js\',
    \'initial_value\' => \'\',
    \'skip_in_form\' => \'0\',
    \'html\' => \'<script>
$nc(function() {
    var display = $nc("[name=\\\'custom_settings[display_as]\\\']"),
        liStyle = $nc("[name=\\\'custom_settings[li_style]\\\']").closest(".nc-field"),
        titleClass = $nc("[name=\\\'custom_settings[title_classname]\\\']").closest(".nc-field");

    function toggle() {
        var val = display.val();
        liStyle.toggle(val === "li");
        titleClass.toggle(val === "li" || val === "a");
    }

    display.on("change", toggle);
    toggle();
});
</script>
\',
  ),
);',
