function init_dependent_field(main_select_selector, dependent_input_selector, should_show_dependent) {
    var dialog = nc.ui.modal_dialog.get_current_dialog(),
        context = dialog ? dialog.get_part("body") : $nc("body"),
        event = "change.tpl_netcat_menu"; // общее пространство имён для всех шаблонов этого компонента

    $nc(context).off(event, main_select_selector).on(event, main_select_selector, function () {
        var main_select = $nc(this),
            dependent_div = main_select
                .closest(".nc-block-menu-custom-settings-container")
                .find(dependent_input_selector)
                .parent(".nc-field");
        should_show_dependent(main_select.val()) ? dependent_div.slideDown() : dependent_div.slideUp();
    });

    $nc(main_select_selector, context).change();
}

init_dependent_field(
    "select[name*=\\\\"[item_image_ratio]\\\\"]",
    "input[name*=\\\\"[item_image_custom_ratio]\\\\"]",
    function(value) { return value === "custom"; }
);
});</script>\',
